using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Service setup ---
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILoggerFactory>();

// --- Tools ---
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearch.SearchAsync(query),
        "web_search",
        "Searches the web for the given query and returns a list of result snippets. " +
        "Use this to gather information about a topic."),

    AIFunctionFactory.Create(
        ([Description("A concise key or title for the note")] string key,
         [Description("The content to save")] string content) =>
        {
            notebook.Save(key, content);
            return $"Note saved under '{key}'.";
        },
        "save_note",
        "Saves a note with a key and content for later reference. " +
        "Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieves all saved notes as a dictionary of key-value pairs. " +
        "Use this to review what has been collected so far."),
};

// --- Agent ---
var agent = new ChatClientAgent(chatClient, new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
});

var instructions = new ChatMessage(ChatRole.System, """
    You are a research assistant. When given a topic:
    1. Use the web_search tool multiple times with different queries to gather diverse information.
    2. Use the save_note tool to record key findings as you go.
    3. After gathering enough information, use get_notes to review everything.
    4. Produce a well-structured summary with sections, key facts, and source attribution.
    Be thorough but concise. Aim for 3-5 searches before summarizing.
    """);

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (type 'exit')      ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        instructions,
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    Console.WriteLine();
    Console.WriteLine("Researching... (the agent will search the web and take notes)");
    Console.WriteLine();

    try
    {
        var session = await agent.CreateSessionAsync();
        var response = await agent.RunAsync(
            messages,
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            }),
            CancellationToken.None);

        Console.WriteLine("── Research Summary ─────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("─────────────────────────────────────────");

        if (response.Usage is { } usage)
        {
            Console.WriteLine(
                $"[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

