     if (topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
         break;

     notebook.Clear();

     var messages = new List<ChatMessage>
     {
         instructions,
         new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
     };

     Console.WriteLine();
     Console.WriteLine("Researching... (the agent will search the web and take notes)");
     Console.WriteLine();

     try
     {
         var session = await agent.CreateSessionAsync();
         var response = await agent.RunAsync(
             messages,
             session,
             new ChatClientAgentRunOptions(new ChatOptions
             {
                 Temperature = 0f,
                 MaxOutputTokens = 2048,
             }),
             CancellationToken.None);

         Console.WriteLine("── Research Summary ─────────────────────");
         Console.WriteLine(response.Text);
         Console.WriteLine("─────────────────────────────────────────");

         if (response.Usage is { } usage)
         {
             Console.WriteLine(
                 $"[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
         }
     }
     catch (Exception ex)
     {
         Console.WriteLine($"Error: {ex.Message}");
     }

     Console.WriteLine();
 }

 Console.WriteLine("Goodbye!");

