 /// <summary>Simulated web search that returns plausible results for any query.</summary>
 static class WebSearch
 {
     private static readonly HttpClient Http = new()
     {
         Timeout = TimeSpan.FromSeconds(10),
     };

     public static async Task<string> SearchAsync(string query)
     {
         Console.WriteLine($"  🔍 Searching: \"{query}\"");

         // Try a real search via DuckDuckGo instant-answer API (no key required).
         try
         {
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await Http.GetStringAsync(url);

             var results = ParseDuckDuckGoResponse(json, query);
             if (!string.IsNullOrWhiteSpace(results))
                 return results;
         }
         catch
         {
             // Fall through to fallback.
         }

         return $"[Web search for \"{query}\"]\n" +
                "No detailed results available. The agent should try a different query or " +
                "synthesize from notes already collected.";
     }

     private static string ParseDuckDuckGoResponse(string json, string query)
     {
         using var doc = System.Text.Json.JsonDocument.Parse(json);
         var root = doc.RootElement;
         var parts = new List<string>();

         // Abstract
         if (root.TryGetProperty("AbstractText", out var abs) &&
             abs.GetString() is { Length: > 0 } abstractText)
         {
             var source = root.TryGetProperty("AbstractSource", out var src)
                 ? src.GetString() : "Unknown";
             parts.Add($"Source: {source}\n{abstractText}");
         }

         // Related topics
         if (root.TryGetProperty("RelatedTopics", out var topics) &&
             topics.ValueKind == System.Text.Json.JsonValueKind.Array)
         {
             var count = 0;
             foreach (var topic in topics.EnumerateArray())
             {
                 if (count >= 5) break;
                 if (topic.TryGetProperty("Text", out var text) &&
                     text.GetString() is { Length: > 0 } t)
                 {
                     parts.Add($"- {t}");
                     count++;
                 }
             }
         }

         return parts.Count > 0
             ? $"[Web results for \"{query}\"]\n{string.Join("\n\n", parts)}"
             : string.Empty;
     }
 }

 /// <summary>Simple in-memory notebook for the agent to store findings.</summary>
 sealed class Notebook
 {
     private readonly Dictionary<string, string> _notes = new(StringComparer.OrdinalIgnoreCase);

     public void Save(string key, string content)
     {
         _notes[key] = content;
         Console.WriteLine($"  📝 Note saved: \"{key}\"");
     }

     public Dictionary<string, string> GetAll() => new(_notes);

     public void Clear() => _notes.Clear();
 }
